86	/**
87	 * AMRMProxyService is a service that runs on each node manager that can be used
88	 * to intercept and inspect messages from application master to the cluster
89	 * resource manager. It listens to messages from the application master and
90	 * creates a request intercepting pipeline instance for each application. The
91	 * pipeline is a chain of interceptor instances that can inspect and modify the
92	 * request/response as needed.
93	 */
94	public class AMRMProxyService extends CompositeService implements
95	    ApplicationMasterProtocol {
96	  private static final Logger LOG = LoggerFactory
97	      .getLogger(AMRMProxyService.class);
98	
99	  private static final String NMSS_USER_KEY = "user";
100	  private static final String NMSS_AMRMTOKEN_KEY = "amrmtoken";
101	
102	  private final Clock clock = new MonotonicClock();
103	  private Server server;
104	  private final Context nmContext;
105	  private final AsyncDispatcher dispatcher;
106	  private InetSocketAddress listenerEndpoint;
107	  private AMRMProxyTokenSecretManager secretManager;
108	  private Map<ApplicationId, RequestInterceptorChainWrapper> applPipelineMap;
109	  private RegistryOperations registry;
110	  private AMRMProxyMetrics metrics;
111	  private FederationStateStoreFacade federationFacade;
112	  private boolean federationEnabled = false;
113	
114	  /**
115	   * Creates an instance of the service.
116	   *
117	   * @param nmContext NM context
118	   * @param dispatcher NM dispatcher
119	   */
120	  public AMRMProxyService(Context nmContext, AsyncDispatcher dispatcher) {
121	    super(AMRMProxyService.class.getName());
122	    Preconditions.checkArgument(nmContext != null, "nmContext is null");
123	    Preconditions.checkArgument(dispatcher != null, "dispatcher is null");
124	    this.nmContext = nmContext;
125	    this.dispatcher = dispatcher;
126	    this.applPipelineMap =
127	        new ConcurrentHashMap<ApplicationId, RequestInterceptorChainWrapper>();
128	
129	    this.dispatcher.register(ApplicationEventType.class,
130	        new ApplicationEventHandler());
131	
132	    metrics = AMRMProxyMetrics.getMetrics();
133	  }
134	
135	  @Override
136	  protected void serviceInit(Configuration conf) throws Exception {
137	    this.secretManager =
138	        new AMRMProxyTokenSecretManager(this.nmContext.getNMStateStore());
139	    this.secretManager.init(conf);
140	
141	    if (conf.getBoolean(YarnConfiguration.AMRM_PROXY_HA_ENABLED,
142	        YarnConfiguration.DEFAULT_AMRM_PROXY_HA_ENABLED)) {
143	      this.registry = FederationStateStoreFacade.createInstance(conf,
144	          YarnConfiguration.YARN_REGISTRY_CLASS,
145	          YarnConfiguration.DEFAULT_YARN_REGISTRY_CLASS,
146	          RegistryOperations.class);
147	      addService(this.registry);
148	    }
149	    this.federationFacade = FederationStateStoreFacade.getInstance();
150	    this.federationEnabled =
151	        conf.getBoolean(YarnConfiguration.FEDERATION_ENABLED,
152	            YarnConfiguration.DEFAULT_FEDERATION_ENABLED);
153	    super.serviceInit(conf);
154	  }
155	
156	  @Override
157	  protected void serviceStart() throws Exception {
158	    LOG.info("Starting AMRMProxyService");
159	    Configuration conf = getConfig();
160	    YarnRPC rpc = YarnRPC.create(conf);
161	    UserGroupInformation.setConfiguration(conf);
162	
163	    this.listenerEndpoint =
164	        conf.getSocketAddr(YarnConfiguration.AMRM_PROXY_ADDRESS,
165	            YarnConfiguration.DEFAULT_AMRM_PROXY_ADDRESS,
166	            YarnConfiguration.DEFAULT_AMRM_PROXY_PORT);
167	
168	    Configuration serverConf = new Configuration(conf);
169	    serverConf.set(
170	        CommonConfigurationKeysPublic.HADOOP_SECURITY_AUTHENTICATION,
171	        SaslRpcServer.AuthMethod.TOKEN.toString());
172	
173	    int numWorkerThreads =
174	        serverConf.getInt(
175	            YarnConfiguration.AMRM_PROXY_CLIENT_THREAD_COUNT,
176	            YarnConfiguration.DEFAULT_AMRM_PROXY_CLIENT_THREAD_COUNT);
177	
178	    this.secretManager.start();
179	
180	    this.server =
181	        rpc.getServer(ApplicationMasterProtocol.class, this,
182	            listenerEndpoint, serverConf, this.secretManager,
183	            numWorkerThreads);
184	
185	    if (conf
186	        .getBoolean(CommonConfigurationKeysPublic.HADOOP_SECURITY_AUTHORIZATION,
187	            false)) {
188	        this.server.refreshServiceAcl(conf, NMPolicyProvider.getInstance());
189	    }
190	
191	    this.server.start();
192	    LOG.info("AMRMProxyService listening on address: "
193	        + this.server.getListenerAddress());
194	    super.serviceStart();
195	  }
196	
197	  @Override
198	  protected void serviceStop() throws Exception {
199	    LOG.info("Stopping AMRMProxyService");
200	    if (this.server != null) {
201	      this.server.stop();
202	    }
203	
204	    this.secretManager.stop();
205	
206	    super.serviceStop();
207	  }
