209	  /**
210	   * Recover from NM state store. Called after serviceInit before serviceStart.
211	   *
212	   * @throws IOException if recover fails
213	   */
214	  public void recover() throws IOException {
215	    LOG.info("Recovering AMRMProxyService");
216	
217	    RecoveredAMRMProxyState state =
218	        this.nmContext.getNMStateStore().loadAMRMProxyState();
219	
220	    this.secretManager.recover(state);
221	
222	    LOG.info("Recovering {} running applications for AMRMProxy",
223	        state.getAppContexts().size());
224	    for (Map.Entry<ApplicationAttemptId, Map<String, byte[]>> entry : state
225	        .getAppContexts().entrySet()) {
226	      ApplicationAttemptId attemptId = entry.getKey();
227	      LOG.info("Recovering app attempt {}", attemptId);
228	
229	      // Try recover for the running application attempt
230	      try {
231	        String user = null;
232	        Token<AMRMTokenIdentifier> amrmToken = null;
233	        for (Map.Entry<String, byte[]> contextEntry : entry.getValue()
234	            .entrySet()) {
235	          if (contextEntry.getKey().equals(NMSS_USER_KEY)) {
236	            user = new String(contextEntry.getValue(), "UTF-8");
237	          } else if (contextEntry.getKey().equals(NMSS_AMRMTOKEN_KEY)) {
238	            amrmToken = new Token<>();
239	            amrmToken.decodeFromUrlString(
240	                new String(contextEntry.getValue(), "UTF-8"));
241	            // Clear the service field, as if RM just issued the token
242	            amrmToken.setService(new Text());
243	          }
244	        }
245	
246	        if (amrmToken == null) {
247	          throw new IOException(
248	              "No amrmToken found for app attempt " + attemptId);
249	        }
250	        if (user == null) {
251	          throw new IOException("No user found for app attempt " + attemptId);
252	        }
253	
254	        // Regenerate the local AMRMToken for the AM
255	        Token<AMRMTokenIdentifier> localToken =
256	            this.secretManager.createAndGetAMRMToken(attemptId);
257	
258	        // Retrieve the AM container credentials from NM context
259	        Credentials amCred = null;
260	        for (Container container : this.nmContext.getContainers().values()) {
261	          LOG.debug("From NM Context container {}", container.getContainerId());
262	          if (container.getContainerId().getApplicationAttemptId().equals(
263	              attemptId) && container.getContainerTokenIdentifier() != null) {
264	            LOG.debug("Container type {}",
265	                container.getContainerTokenIdentifier().getContainerType());
266	            if (container.getContainerTokenIdentifier()
267	                .getContainerType() == ContainerType.APPLICATION_MASTER) {
268	              LOG.info("AM container {} found in context, has credentials: {}",
269	                  container.getContainerId(),
270	                  (container.getCredentials() != null));
271	              amCred = container.getCredentials();
272	            }
273	          }
274	        }
275	        if (amCred == null) {
276	          LOG.error("No credentials found for AM container of {}. "
277	              + "Yarn registry access might not work", attemptId);
278	        }
279	
280	        // Create the intercepter pipeline for the AM
281	        initializePipeline(attemptId, user, amrmToken, localToken,
282	            entry.getValue(), true, amCred);
283	      } catch (Throwable e) {
284	        LOG.error("Exception when recovering " + attemptId
285	            + ", removing it from NMStateStore and move on", e);
286	        this.metrics.incrFailedAppRecoveryCount();
287	        this.nmContext.getNMStateStore().removeAMRMProxyAppContext(attemptId);
288	      }
289	    }
290	  }
291	
292	  /**
293	   * This is called by the AMs started on this node to register with the RM.
294	   * This method does the initial authorization and then forwards the request to
295	   * the application instance specific intercepter chain.
296	   */
297	  @Override
298	  public RegisterApplicationMasterResponse registerApplicationMaster(
299	      RegisterApplicationMasterRequest request) throws YarnException,
300	      IOException {
301	    long startTime = clock.getTime();
302	    try {
303	      RequestInterceptorChainWrapper pipeline =
304	          authorizeAndGetInterceptorChain();
305	      LOG.info("Registering application master." + " Host:" + request.getHost()
306	          + " Port:" + request.getRpcPort() + " Tracking Url:" + request
307	          .getTrackingUrl() + " for application " + pipeline
308	          .getApplicationAttemptId());
309	      RegisterApplicationMasterResponse response =
310	          pipeline.getRootInterceptor().registerApplicationMaster(request);
311	
312	      long endTime = clock.getTime();
313	      this.metrics.succeededRegisterAMRequests(endTime - startTime);
314	      LOG.info("RegisterAM processing finished in {} ms for application {}",
315	          endTime - startTime, pipeline.getApplicationAttemptId());
316	      return response;
317	    } catch (Throwable t) {
318	      this.metrics.incrFailedRegisterAMRequests();
319	      throw t;
320	    }
321	  }
322	
323	  /**
324	   * This is called by the AMs started on this node to unregister from the RM.
325	   * This method does the initial authorization and then forwards the request to
326	   * the application instance specific intercepter chain.
327	   */
328	  @Override
329	  public FinishApplicationMasterResponse finishApplicationMaster(
330	      FinishApplicationMasterRequest request) throws YarnException,
331	      IOException {
332	    long startTime = clock.getTime();
333	    try {
334	      RequestInterceptorChainWrapper pipeline =
335	          authorizeAndGetInterceptorChain();
336	      LOG.info("Finishing application master for {}. Tracking Url: {}",
337	          pipeline.getApplicationAttemptId(), request.getTrackingUrl());
338	      FinishApplicationMasterResponse response =
339	          pipeline.getRootInterceptor().finishApplicationMaster(request);
340	
341	      long endTime = clock.getTime();
342	      this.metrics.succeededFinishAMRequests(endTime - startTime);
343	      LOG.info("FinishAM finished with isUnregistered = {} in {} ms for {}",
344	          response.getIsUnregistered(), endTime - startTime,
345	          pipeline.getApplicationAttemptId());
346	      return response;
347	    } catch (Throwable t) {
348	      this.metrics.incrFailedFinishAMRequests();
349	      throw t;
350	    }
351	  }
352	
353	  /**
354	   * This is called by the AMs started on this node to send heart beat to RM.
355	   * This method does the initial authorization and then forwards the request to
356	   * the application instance specific pipeline, which is a chain of request
357	   * intercepter objects. One application request processing pipeline is created
358	   * per AM instance.
359	   */
360	  @Override
361	  public AllocateResponse allocate(AllocateRequest request)
362	      throws YarnException, IOException {
363	    long startTime = clock.getTime();
364	    try {
365	      AMRMTokenIdentifier amrmTokenIdentifier =
366	          YarnServerSecurityUtils.authorizeRequest();
367	      RequestInterceptorChainWrapper pipeline =
368	          getInterceptorChain(amrmTokenIdentifier);
369	      AllocateResponse allocateResponse =
370	          pipeline.getRootInterceptor().allocate(request);
371	
372	      updateAMRMTokens(amrmTokenIdentifier, pipeline, allocateResponse);
373	
374	      long endTime = clock.getTime();
375	      this.metrics.succeededAllocateRequests(endTime - startTime);
376	      LOG.info("Allocate processing finished in {} ms for application {}",
377	          endTime - startTime, pipeline.getApplicationAttemptId());
378	      return allocateResponse;
379	    } catch (Throwable t) {
380	      this.metrics.incrFailedAllocateRequests();
381	      throw t;
382	    }
383	  }
384	
385	  /**
386	   * Callback from the ContainerManager implementation for initializing the
387	   * application request processing pipeline.
388	   *
389	   * @param request - encapsulates information for starting an AM
390	   * @throws IOException if fails
391	   * @throws YarnException if fails
392	   */
393	  public void processApplicationStartRequest(StartContainerRequest request)
394	      throws IOException, YarnException {
395	    long startTime = clock.getTime();
396	    try {
397	      ContainerTokenIdentifier containerTokenIdentifierForKey =
398	          BuilderUtils.newContainerTokenIdentifier(request.getContainerToken());
399	      ApplicationAttemptId appAttemptId =
400	          containerTokenIdentifierForKey.getContainerID()
401	              .getApplicationAttemptId();
402	      ApplicationId applicationID = appAttemptId.getApplicationId();
403	      // Checking if application is there in federation state store only
404	      // if federation is enabled. If
405	      // application is submitted to router then it adds it in statestore.
406	      // if application is not found in statestore that means its
407	      // submitted to RM
408	      if (!checkIfAppExistsInStateStore(applicationID)) {
409	        return;
410	      }
411	      LOG.info("Callback received for initializing request "
412	          + "processing pipeline for an AM");
413	      Credentials credentials = YarnServerSecurityUtils
414	          .parseCredentials(request.getContainerLaunchContext());
415	
416	      Token<AMRMTokenIdentifier> amrmToken =
417	          getFirstAMRMToken(credentials.getAllTokens());
418	      if (amrmToken == null) {
419	        throw new YarnRuntimeException(
420	            "AMRMToken not found in the start container request for "
421	                + "application:" + appAttemptId.toString());
422	      }
423	
424	      // Substitute the existing AMRM Token with a local one. Keep the rest of
425	      // the tokens in the credentials intact.
426	      Token<AMRMTokenIdentifier> localToken =
427	          this.secretManager.createAndGetAMRMToken(appAttemptId);
428	      credentials.addToken(localToken.getService(), localToken);
429	
430	      DataOutputBuffer dob = new DataOutputBuffer();
431	      credentials.writeTokenStorageToStream(dob);
432	      request.getContainerLaunchContext()
433	          .setTokens(ByteBuffer.wrap(dob.getData(), 0, dob.getLength()));
434	
435	      initializePipeline(appAttemptId,
436	          containerTokenIdentifierForKey.getApplicationSubmitter(), amrmToken,
437	          localToken, null, false, credentials);
438	
439	      long endTime = clock.getTime();
440	      this.metrics.succeededAppStartRequests(endTime - startTime);
441	    } catch (Throwable t) {
442	      this.metrics.incrFailedAppStartRequests();
443	      throw t;
444	    }
445	  }
