447	  /**
448	   * Initializes the request intercepter pipeline for the specified application.
449	   *
450	   * @param applicationAttemptId attempt id
451	   * @param user user name
452	   * @param amrmToken amrmToken issued by RM
453	   * @param localToken amrmToken issued by AMRMProxy
454	   * @param recoveredDataMap the recovered states for AMRMProxy from NMSS
455	   * @param isRecovery whether this is to recover a previously existing pipeline
456	   */
457	  protected void initializePipeline(ApplicationAttemptId applicationAttemptId,
458	      String user, Token<AMRMTokenIdentifier> amrmToken,
459	      Token<AMRMTokenIdentifier> localToken,
460	      Map<String, byte[]> recoveredDataMap, boolean isRecovery,
461	      Credentials credentials) {
462	    RequestInterceptorChainWrapper chainWrapper = null;
463	    synchronized (applPipelineMap) {
464	      if (applPipelineMap
465	          .containsKey(applicationAttemptId.getApplicationId())) {
466	        LOG.warn("Request to start an already existing appId was received. "
467	            + " This can happen if an application failed and a new attempt "
468	            + "was created on this machine.  ApplicationId: "
469	            + applicationAttemptId.toString());
470	
471	        RequestInterceptorChainWrapper chainWrapperBackup =
472	            this.applPipelineMap.get(applicationAttemptId.getApplicationId());
473	        if (chainWrapperBackup != null
474	            && chainWrapperBackup.getApplicationAttemptId() != null
475	            && !chainWrapperBackup.getApplicationAttemptId()
476	                .equals(applicationAttemptId)) {
477	          // TODO: revisit in AMRMProxy HA in YARN-6128
478	          // Remove the existing pipeline
479	          LOG.info("Remove the previous pipeline for ApplicationId: "
480	              + applicationAttemptId.toString());
481	          RequestInterceptorChainWrapper pipeline =
482	              applPipelineMap.remove(applicationAttemptId.getApplicationId());
483	
484	          if (!isRecovery && this.nmContext.getNMStateStore() != null) {
485	            try {
486	              this.nmContext.getNMStateStore()
487	                  .removeAMRMProxyAppContext(applicationAttemptId);
488	            } catch (IOException e) {
489	              LOG.error("Error removing AMRMProxy application context for "
490	                  + applicationAttemptId, e);
491	            }
492	          }
493	
494	          try {
495	            pipeline.getRootInterceptor().shutdown();
496	          } catch (Throwable ex) {
497	            LOG.warn(
498	                "Failed to shutdown the request processing pipeline for app:"
499	                    + applicationAttemptId.getApplicationId(),
500	                ex);
501	          }
502	        } else {
503	          return;
504	        }
505	      }
506	
507	      chainWrapper = new RequestInterceptorChainWrapper();
508	      this.applPipelineMap.put(applicationAttemptId.getApplicationId(),
509	          chainWrapper);
510	    }
511	
512	    // We register the pipeline instance in the map first and then initialize it
513	    // later because chain initialization can be expensive and we would like to
514	    // release the lock as soon as possible to prevent other applications from
515	    // blocking when one application's chain is initializing
516	    LOG.info("Initializing request processing pipeline for application. "
517	        + " ApplicationId:" + applicationAttemptId + " for the user: "
518	        + user);
519	
520	    try {
521	      RequestInterceptor interceptorChain =
522	          this.createRequestInterceptorChain();
523	      interceptorChain.init(
524	          createApplicationMasterContext(this.nmContext, applicationAttemptId,
525	              user, amrmToken, localToken, credentials, this.registry));
526	      if (isRecovery) {
527	        if (recoveredDataMap == null) {
528	          throw new YarnRuntimeException(
529	              "null recoveredDataMap recieved for recover");
530	        }
531	        interceptorChain.recover(recoveredDataMap);
532	      }
533	      chainWrapper.init(interceptorChain, applicationAttemptId);
534	
535	      if (!isRecovery && this.nmContext.getNMStateStore() != null) {
536	        try {
537	          this.nmContext.getNMStateStore().storeAMRMProxyAppContextEntry(
538	              applicationAttemptId, NMSS_USER_KEY, user.getBytes("UTF-8"));
539	          this.nmContext.getNMStateStore().storeAMRMProxyAppContextEntry(
540	              applicationAttemptId, NMSS_AMRMTOKEN_KEY,
541	              amrmToken.encodeToUrlString().getBytes("UTF-8"));
542	        } catch (IOException e) {
543	          LOG.error("Error storing AMRMProxy application context entry for "
544	              + applicationAttemptId, e);
545	        }
546	      }
547	    } catch (Exception e) {
548	      this.applPipelineMap.remove(applicationAttemptId.getApplicationId());
549	      throw e;
550	    }
551	  }
