553	  /**
554	   * Shuts down the request processing pipeline for the specified application
555	   * attempt id.
556	   *
557	   * @param applicationId application id
558	   */
559	  protected void stopApplication(ApplicationId applicationId) {
560	    Preconditions.checkArgument(applicationId != null,
561	        "applicationId is null");
562	    RequestInterceptorChainWrapper pipeline =
563	        this.applPipelineMap.remove(applicationId);
564	
565	    if (pipeline == null) {
566	      LOG.info(
567	          "No interceptor pipeline for application {},"
568	              + " likely because its AM is not run in this node.",
569	          applicationId);
570	    } else {
571	      // Remove the appAttempt in AMRMTokenSecretManager
572	      this.secretManager
573	          .applicationMasterFinished(pipeline.getApplicationAttemptId());
574	
575	      LOG.info("Stopping the request processing pipeline for application: "
576	          + applicationId);
577	      try {
578	        pipeline.getRootInterceptor().shutdown();
579	      } catch (Throwable ex) {
580	        LOG.warn(
581	            "Failed to shutdown the request processing pipeline for app:"
582	                + applicationId, ex);
583	      }
584	
585	      // Remove the app context from NMSS after the interceptors are shutdown
586	      if (this.nmContext.getNMStateStore() != null) {
587	        try {
588	          this.nmContext.getNMStateStore()
589	              .removeAMRMProxyAppContext(pipeline.getApplicationAttemptId());
590	        } catch (IOException e) {
591	          LOG.error("Error removing AMRMProxy application context for "
592	              + applicationId, e);
593	        }
594	      }
595	    }
596	  }
