598	  private void updateAMRMTokens(AMRMTokenIdentifier amrmTokenIdentifier,
599	      RequestInterceptorChainWrapper pipeline,
600	      AllocateResponse allocateResponse) {
601	    AMRMProxyApplicationContextImpl context =
602	        (AMRMProxyApplicationContextImpl) pipeline.getRootInterceptor()
603	            .getApplicationContext();
604	
605	    // check to see if the RM has issued a new AMRMToken & accordingly update
606	    // the real ARMRMToken in the current context
607	    if (allocateResponse.getAMRMToken() != null) {
608	      LOG.info("RM rolled master-key for amrm-tokens");
609	
610	      org.apache.hadoop.yarn.api.records.Token token =
611	          allocateResponse.getAMRMToken();
612	
613	      // Do not propagate this info back to AM
614	      allocateResponse.setAMRMToken(null);
615	
616	      org.apache.hadoop.security.token.Token<AMRMTokenIdentifier> newToken =
617	          ConverterUtils.convertFromYarn(token, (Text) null);
618	
619	      // Update the AMRMToken in context map, and in NM state store if it is
620	      // different
621	      if (context.setAMRMToken(newToken)
622	          && this.nmContext.getNMStateStore() != null) {
623	        try {
624	          this.nmContext.getNMStateStore().storeAMRMProxyAppContextEntry(
625	              context.getApplicationAttemptId(), NMSS_AMRMTOKEN_KEY,
626	              newToken.encodeToUrlString().getBytes("UTF-8"));
627	        } catch (IOException e) {
628	          LOG.error("Error storing AMRMProxy application context entry for "
629	              + context.getApplicationAttemptId(), e);
630	        }
631	      }
632	    }
633	
634	    // Check if the local AMRMToken is rolled up and update the context and
635	    // response accordingly
636	    MasterKeyData nextMasterKey =
637	        this.secretManager.getNextMasterKeyData();
638	
639	    if (nextMasterKey != null
640	        && nextMasterKey.getMasterKey().getKeyId() != amrmTokenIdentifier
641	            .getKeyId()) {
642	      Token<AMRMTokenIdentifier> localToken = context.getLocalAMRMToken();
643	      if (nextMasterKey.getMasterKey().getKeyId() != context
644	          .getLocalAMRMTokenKeyId()) {
645	        LOG.info("The local AMRMToken has been rolled-over."
646	            + " Send new local AMRMToken back to application: "
647	            + pipeline.getApplicationId());
648	        localToken =
649	            this.secretManager.createAndGetAMRMToken(pipeline
650	                .getApplicationAttemptId());
651	        context.setLocalAMRMToken(localToken);
652	      }
653	
654	      allocateResponse
655	          .setAMRMToken(org.apache.hadoop.yarn.api.records.Token
656	              .newInstance(localToken.getIdentifier(), localToken
657	                  .getKind().toString(), localToken.getPassword(),
658	                  localToken.getService().toString()));
659	    }
660	  }
