731	  /**
732	   * Returns the comma separated intercepter class names from the configuration.
733	   *
734	   * @param conf configuration
735	   * @return the intercepter class names as an instance of ArrayList
736	   */
737	  private List<String> getInterceptorClassNames(Configuration conf) {
738	    String configuredInterceptorClassNames =
739	        conf.get(
740	            YarnConfiguration.AMRM_PROXY_INTERCEPTOR_CLASS_PIPELINE,
741	            YarnConfiguration.DEFAULT_AMRM_PROXY_INTERCEPTOR_CLASS_PIPELINE);
742	
743	    List<String> interceptorClassNames = new ArrayList<String>();
744	    Collection<String> tempList =
745	        StringUtils.getStringCollection(configuredInterceptorClassNames);
746	    for (String item : tempList) {
747	      interceptorClassNames.add(item.trim());
748	    }
749	
750	    // Make sure DistributedScheduler is present at the beginning of the chain.
751	    if (this.nmContext.isDistributedSchedulingEnabled()) {
752	      interceptorClassNames.add(0, DistributedScheduler.class.getName());
753	    }
754	
755	    return interceptorClassNames;
756	  }
