804	  @SuppressWarnings("unchecked")
805	  private Token<AMRMTokenIdentifier> getFirstAMRMToken(
806	      Collection<Token<? extends TokenIdentifier>> allTokens) {
807	    Iterator<Token<? extends TokenIdentifier>> iter = allTokens.iterator();
808	    while (iter.hasNext()) {
809	      Token<? extends TokenIdentifier> token = iter.next();
810	      if (token.getKind().equals(AMRMTokenIdentifier.KIND_NAME)) {
811	        return (Token<AMRMTokenIdentifier>) token;
812	      }
813	    }
814	
815	    return null;
816	  }
