598	  private void updateAMRMTokens(AMRMTokenIdentifier amrmTokenIdentifier,
599	      RequestInterceptorChainWrapper pipeline,
600	      AllocateResponse allocateResponse) {
601	
602	    AMRMProxyApplicationContextImpl context =
603	        (AMRMProxyApplicationContextImpl) pipeline.getRootInterceptor().getApplicationContext();
604	
605	    try {
606	      long startTime = clock.getTime();
607	
608	      // check to see if the RM has issued a new AMRMToken & accordingly update
609	      // the real ARMRMToken in the current context
610	      if (allocateResponse.getAMRMToken() != null) {
611	        LOG.info("RM rolled master-key for amrm-tokens.");
612	
613	        org.apache.hadoop.yarn.api.records.Token token = allocateResponse.getAMRMToken();
614	
615	        // Do not propagate this info back to AM
616	        allocateResponse.setAMRMToken(null);
617	
618	        org.apache.hadoop.security.token.Token<AMRMTokenIdentifier> newToken =
619	                ConverterUtils.convertFromYarn(token, (Text) null);
620	
621	        // Update the AMRMToken in context map, and in NM state store if it is
622	        // different
623	        if (context.setAMRMToken(newToken) && this.nmContext.getNMStateStore() != null) {
624	          this.nmContext.getNMStateStore().storeAMRMProxyAppContextEntry(
625	              context.getApplicationAttemptId(), NMSS_AMRMTOKEN_KEY,
626	              newToken.encodeToUrlString().getBytes(StandardCharsets.UTF_8));
627	        }
628	      }
629	
630	      // Check if the local AMRMToken is rolled up and update the context and
631	      // response accordingly
632	      MasterKeyData nextMasterKey = this.secretManager.getNextMasterKeyData();
633	
634	      if (nextMasterKey != null) {
635	        MasterKey masterKey = nextMasterKey.getMasterKey();
636	        if (masterKey.getKeyId() != amrmTokenIdentifier.getKeyId()) {
637	          Token<AMRMTokenIdentifier> localToken = context.getLocalAMRMToken();
638	          if (masterKey.getKeyId() != context.getLocalAMRMTokenKeyId()) {
639	            LOG.info("The local AMRMToken has been rolled-over."
640	                + " Send new local AMRMToken back to application: {}",
641	                pipeline.getApplicationId());
642	            localToken = this.secretManager.createAndGetAMRMToken(
643	                pipeline.getApplicationAttemptId());
644	            context.setLocalAMRMToken(localToken);
645	          }
646	
647	          allocateResponse
648	              .setAMRMToken(org.apache.hadoop.yarn.api.records.Token
649	                  .newInstance(localToken.getIdentifier(), localToken
650	                      .getKind().toString(), localToken.getPassword(),
651	                      localToken.getService().toString()));
652	        }
653	      }
654	      long endTime = clock.getTime();
655	      this.metrics.succeededUpdateTokenRequests(endTime - startTime);
656	    } catch (IOException e) {
657	      LOG.error("Error storing AMRMProxy application context entry for {}.",
658	          context.getApplicationAttemptId(), e);
659	      this.metrics.incrFailedUpdateAMRMTokenRequests();
660	    }
661	  }
