203	  /**
204	   * Recover from NM state store. Called after serviceInit before serviceStart.
205	   *
206	   * @throws IOException if recover fails
207	   */
208	  public void recover() throws IOException {
209	    LOG.info("Recovering AMRMProxyService.");
210	
211	    RecoveredAMRMProxyState state =
212	        this.nmContext.getNMStateStore().loadAMRMProxyState();
213	
214	    this.secretManager.recover(state);
215	
216	    LOG.info("Recovering {} running applications for AMRMProxy.",
217	        state.getAppContexts().size());
218	
219	    for (Map.Entry<ApplicationAttemptId, Map<String, byte[]>> entry : state
220	        .getAppContexts().entrySet()) {
221	      ApplicationAttemptId attemptId = entry.getKey();
222	      LOG.info("Recovering app attempt {}.", attemptId);
223	      long startTime = clock.getTime();
224	
225	      // Try recover for the running application attempt
226	      try {
227	        String user = null;
228	        Token<AMRMTokenIdentifier> amrmToken = null;
229	        for (Map.Entry<String, byte[]> contextEntry : entry.getValue()
230	            .entrySet()) {
231	          if (contextEntry.getKey().equals(NMSS_USER_KEY)) {
232	            user = new String(contextEntry.getValue(), StandardCharsets.UTF_8);
233	          } else if (contextEntry.getKey().equals(NMSS_AMRMTOKEN_KEY)) {
234	            amrmToken = new Token<>();
235	            amrmToken.decodeFromUrlString(
236	                new String(contextEntry.getValue(), StandardCharsets.UTF_8));
237	            // Clear the service field, as if RM just issued the token
238	            amrmToken.setService(new Text());
239	          }
240	        }
241	
242	        if (amrmToken == null) {
243	          throw new IOException("No amrmToken found for app attempt " + attemptId);
244	        }
245	        if (user == null) {
246	          throw new IOException("No user found for app attempt " + attemptId);
247	        }
248	
249	        // Regenerate the local AMRMToken for the AM
250	        Token<AMRMTokenIdentifier> localToken =
251	            this.secretManager.createAndGetAMRMToken(attemptId);
252	
253	        // Retrieve the AM container credentials from NM context
254	        Credentials amCred = null;
255	        for (Container container : this.nmContext.getContainers().values()) {
256	          LOG.debug("From NM Context container {}.", container.getContainerId());
257	          if (container.getContainerId().getApplicationAttemptId().equals(
258	              attemptId) && container.getContainerTokenIdentifier() != null) {
259	            LOG.debug("Container type {}.",
260	                container.getContainerTokenIdentifier().getContainerType());
261	            if (container.getContainerTokenIdentifier()
262	                .getContainerType() == ContainerType.APPLICATION_MASTER) {
263	              LOG.info("AM container {} found in context, has credentials: {}.",
264	                  container.getContainerId(),
265	                  (container.getCredentials() != null));
266	              amCred = container.getCredentials();
267	            }
268	          }
269	        }
270	        if (amCred == null) {
271	          LOG.error("No credentials found for AM container of {}. "
272	              + "Yarn registry access might not work.", attemptId);
273	        }
274	
275	        // Create the interceptor pipeline for the AM
276	        initializePipeline(attemptId, user, amrmToken, localToken,
277	            entry.getValue(), true, amCred);
278	        long endTime = clock.getTime();
279	        this.metrics.succeededRecoverRequests(endTime - startTime);
280	      } catch (Throwable e) {
281	        LOG.error("Exception when recovering {}, removing it from NMStateStore and move on.",
282	            attemptId, e);
283	        this.metrics.incrFailedAppRecoveryCount();
284	        this.nmContext.getNMStateStore().removeAMRMProxyAppContext(attemptId);
285	      }
286	    }
287	  }
